package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"
)

const (
	maxRetries    = 3
	rateLimitRPS  = 100
	hmacSecret    = "production-secret-key-2024"
	oauthCallback = "/oauth/callback"
)

var (
	allowedHosts = []string{"auth.example.com", "login.example.com"}
	rlMu         sync.Mutex
	rlTokens     = make(map[string]*rateLimiter)
)

type rateLimiter struct {
	tokens    float64
	lastCheck time.Time
}

func getRateLimiter(ip string) *rateLimiter {
	rlMu.Lock()
	defer rlMu.Unlock()
	if rl, ok := rlTokens[ip]; ok {
		return rl
	}
	rl := &rateLimiter{tokens: rateLimitRPS, lastCheck: time.Now()}
	rlTokens[ip] = rl
	return rl
}

func (rl *rateLimiter) Allow() bool {
	now := time.Now()
	elapsed := now.Sub(rl.lastCheck).Seconds()
	rl.lastCheck = now
	rl.tokens += elapsed * rateLimitRPS
	if rl.tokens > rateLimitRPS {
		rl.tokens = rateLimitRPS
	}
	if rl.tokens < 1 {
		return false
	}
	rl.tokens--
	return true
}

func computeStateMAC(redirectURI string) string {
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	mac.Write([]byte(redirectURI))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateStateMAC(redirectURI, providedMAC string) bool {
	expected := computeStateMAC(redirectURI)
	return hmac.Equal([]byte(expected), []byte(providedMAC))
}

func normalizeRedirectURI(rawURI string) (string, error) {
	parsed, err := url.Parse(rawURI)
	if err != nil {
		return "", err
	}
	// Normalize: lowercase scheme and host
	parsed.Scheme = strings.ToLower(parsed.Scheme)
	parsed.Host = strings.ToLower(parsed.Host)
	return parsed.String(), nil
}

func isAllowedRedirect(redirectURI string) bool {
	parsed, err := url.Parse(redirectURI)
	if err != nil {
		return false
	}
	host := parsed.Hostname()
	for _, allowed := range allowedHosts {
		if host == allowed {
			return true
		}
		// Allow subdomains of allowed hosts
		if strings.HasSuffix(host, "."+allowed) {
			return true
		}
	}
	return false
}

func retryableProxy(target *url.URL, w http.ResponseWriter, r *http.Request) {
	proxy := httputil.NewSingleHostReverseProxy(target)
	var lastErr error
	for attempt := 0; attempt < maxRetries; attempt++ {
		recorder := &responseRecorder{ResponseWriter: w, statusCode: 200}
		proxy.ServeHTTP(recorder, r)
		if recorder.statusCode < 500 {
			return
		}
		lastErr = fmt.Errorf("upstream returned %d", recorder.statusCode)
		time.Sleep(time.Duration(attempt+1) * 100 * time.Millisecond)
	}
	http.Error(w, fmt.Sprintf("upstream error after retries: %v", lastErr), http.StatusBadGateway)
}

type responseRecorder struct {
	http.ResponseWriter
	statusCode int
}

func (rr *responseRecorder) WriteHeader(code int) {
	rr.statusCode = code
	rr.ResponseWriter.WriteHeader(code)
}

func oauthCallbackHandler(w http.ResponseWriter, r *http.Request) {
	redirectURI := r.URL.Query().Get("redirect_uri")
	state := r.URL.Query().Get("state")

	if redirectURI == "" || state == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	normalized, err := normalizeRedirectURI(redirectURI)
	if err != nil {
		http.Error(w, "invalid redirect_uri", http.StatusBadRequest)
		return
	}

	// Validate the HMAC state token against the ORIGINAL redirect_uri
	// This ensures the redirect was initiated by us
	if !validateStateMAC(redirectURI, state) {
		http.Error(w, "invalid state token", http.StatusForbidden)
		return
	}

	// Check if the normalized URI points to an allowed host
	if !isAllowedRedirect(normalized) {
		http.Error(w, "redirect not allowed", http.StatusForbidden)
		return
	}

	http.Redirect(w, r, normalized, http.StatusFound)
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	clientIP := strings.Split(r.RemoteAddr, ":")[0]
	rl := getRateLimiter(clientIP)
	if !rl.Allow() {
		http.Error(w, "rate limited", http.StatusTooManyRequests)
		return
	}

	if r.URL.Path == oauthCallback {
		oauthCallbackHandler(w, r)
		return
	}

	target, _ := url.Parse("http://backend:8080")
	retryableProxy(target, w, r)
}

func main() {
	http.HandleFunc("/", proxyHandler)
	fmt.Println("Proxy listening on :8443")
	http.ListenAndServe(":8443", nil)
}
